// Simulace přihlášeného uživatele
export const CURRENT_USER_ID = "user1"; // 'user1' je "you"
export const CURRENT_USER_NAME = "you";

// Výchozí data
export const initialLists = [
  {
    id: "list1",
    name: "Weekly Groceries",
    owner: "user1", // 'user1' je vlastník
    members: ["user1", "user2", "user3"], // 3 členové
    archived: false,
    items: [
      { id: "item1", name: "Milk", solved: false },
      { id: "item2", name: "Bread", solved: true },
      { id: "item3", name: "Cheese", solved: false },
    ],
  },
  {
    id: "list2",
    name: "Party Supplies",
    owner: "user2", // 'user2' je Sarah
    members: ["user2", "user1"], // 2 členové, 'user1' (ty) jsi člen
    archived: false,
    items: [{ id: "item4", name: "Balloons", solved: false }],
  },
  {
    id: "list3",
    name: "Christmas Shopping",
    owner: "user1", // 'user1' je vlastník
    members: ["user1"], // Jen 1 člen
    archived: false,
    items: [],
  },
  {
    id: "list4",
    name: "Old Vacation List",
    owner: "user1",
    members: ["user1"],
    archived: true, // Archivovaný seznam
    items: [{ id: "item5", name: "Sunscreen", solved: true }],
  },
];
